-- Timeless Movies Film Academy (TMFA): the 72-topic curriculum as an UNPUBLISHED
-- programme — one module per pack topic, one draft lesson per module, and one
-- 85% checkpoint quiz per module.
--
-- Source: TMFA_CURRICULUM_IMPORT.json (schema 1.0, 13 courses, 72 topics), in pack
-- order: Acting for Camera A01–A24 (stages L1–L4), then C01-T1 … C12-T4 (the
-- L1–L4 survey/specialization courses, stored as stage 'survey'). order_index is
-- 0..71, contiguous, grouped by course exactly as the pack lists them. A04 uses
-- the full TMFA_A04_COMPLETE_SAMPLE_LESSON.md; every other lesson is the pack brief.
--
-- NOTHING here is published. Every lesson opens with a visible
-- "DRAFT — FACULTY REVIEW BRIEF ONLY" marker. The programme goes live only after
-- faculty approve the content AND each topic has >= 20 approved bank items (the
-- exam publish preflight enforces the pool; is_published stays false here).
--
-- Checkpoint draw convention (shared with the question importer): bank items are
-- keyed film_module_code = pack topic_id verbatim ('A01', 'C01-T1') and
-- film_stage = 'L1'..'L4' or 'survey'. Each exam draws 10 from its own topic.
--
-- Additive and idempotent: fixed slug, ids derived with md5('tmfa-…:' || topic_id),
-- ON CONFLICT DO NOTHING everywhere, so a re-run inserts nothing and never
-- overwrites faculty edits. No UPDATE, DROP, rename or type change.
-- Generated from the pack data; data-only seed.

INSERT INTO public.academy_programs (
  id, title, slug, description, batch_id, sequential_completion_required,
  estimated_duration_weeks, is_published, is_default
)
VALUES (
  md5('tmfa-programme')::uuid,
  'Timeless Movies Film Academy — Professional Filmmaker Pathway',
  'tmfa-professional-filmmaker-pathway',
  'Learn Film. Make Movies. Acting for Camera (A01–A24) plus twelve shared filmmaking department courses (C01–C12), 72 topics in all. Each topic unlocks the next only after a checkpoint score of 85% or more. DRAFT — faculty review; not yet published.',
  NULL, true, 24, false, false
)
ON CONFLICT DO NOTHING;

DO $seed$
DECLARE
  -- Pack topics in pack order (ord 0..71); stage normalised to L1..L4 | survey.
  topics jsonb := $tmfa$[
{"ord": 0, "topic_id": "A01", "course_name": "Acting for Camera", "stage": "L1", "title": "What an actor actually does", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "An actor does more than display emotion. In a scripted scene, the actor makes purposeful choices **under imagined circumstances** while remaining responsive to partners and camera. Compare two deliveries of “You came back”: one as a polite greeting, one as a concealed accusation. The words do not change; objectives, pauses, gaze and breath do. The audience reads behavior, not the actor's private explanation. **Demonstrate:** record both deliveries in identical framing. **Pitfall:** playing “anger” as a facial mask. **Practice:** invent three playable intentions for the line; have a partner identify the intention without being told. **Evidence:** purposeful physical/vocal change and credible response.", "outcomes": ["A01-LO1 — playable intention", "A01-LO2 — same line, different meaning", "A01-LO3 — listening before delivery", "A01-LO4 — emotional display", "A01-LO5 — repeatable choice"]},
{"ord": 1, "topic_id": "A02", "course_name": "Acting for Camera", "stage": "L1", "title": "Set etiquette and consent", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "A film set is a coordinated workplace. The actor takes direction from the director through agreed set channels, respects the first AD's schedule, maintains quiet during rolling, knows the route for safety concerns, and does not touch another performer or change physical choreography without agreement. “Action” begins the take, but a safety concern can stop it. Learn call sheet essentials: time, location, scenes, transport, emergency contact and required wardrobe. **Demonstrate:** a safe call-time-to-wrap walkthrough. **Pitfall:** treating urgency as permission to bypass a safety protocol. **Practice:** read a sample call sheet and identify an unsafe change; report it through the right channel. **Evidence:** accurate briefing and boundary-setting.", "outcomes": ["A02-LO1 — call sheet", "A02-LO2 — rolling protocol", "A02-LO3 — safety intervention", "A02-LO4 — physical contact", "A02-LO5 — direction changes"]},
{"ord": 2, "topic_id": "A03", "course_name": "Acting for Camera", "stage": "L1", "title": "Script reading and factual analysis", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "On first read, separate facts **explicitly in the script** from ideas the actor invents. Mark scene heading (INT/EXT, place, time), action lines, character cues and dialogue. Record what is known about relationships, timing, location and events just before the scene. Ask: what changes by the end? Avoid deciding how to say every line before you understand the sequence. **Demonstrate:** annotate a two-page family-conflict scene. **Pitfall:** mistaking an inferred backstory for an established script fact. **Practice:** produce a fact/inference table with evidence line references. **Evidence:** coherent given circumstances.", "outcomes": ["A03-LO1 — scene headings", "A03-LO2 — facts versus inference", "A03-LO3 — character relationships", "A03-LO4 — preceding event", "A03-LO5 — scene change"]},
{"ord": 3, "topic_id": "A04", "course_name": "Acting for Camera", "stage": "L1", "title": "Objective, obstacle and stakes", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "An **objective** is what the character wants from someone now, expressible with an active verb such as persuade, hide, protect or confront. An **obstacle** resists that wish. **Stakes** explain why the outcome matters. In a Lagos apartment dispute, “be sad” is not an actionable objective; “convince my landlord to give me another week” is. Strong scene work tracks what a character does when the first tactic fails. **Demonstrate:** same lines with low and high stakes. **Pitfall:** confusing the actor's preferred emotion with the character's target. **Practice:** write a “I want X from Y before Z, but…” statement. **Evidence:** partner-directed action with visible stakes.", "outcomes": ["A04-LO1 — objective", "A04-LO2 — obstacle", "A04-LO3 — stakes", "A04-LO4 — tactic shift", "A04-LO5 — scene preparation"]},
{"ord": 4, "topic_id": "A05", "course_name": "Acting for Camera", "stage": "L1", "title": "Beats and tactics", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "A **beat** is a meaningful change in intention, information, action or relationship within a scene. A **tactic** is what the character tries to obtain the objective: flatter, bargain, threaten, confess. When the partner refuses, the actor can change tactics without changing the scene's overall goal. Mark beats at a shift in action rather than at every punctuation mark. **Demonstrate:** a mother persuading a daughter to stay home, first by joking, then revealing a secret. **Pitfall:** playing every line with identical force. **Practice:** mark three turning points and perform each with a different playable tactic. **Evidence:** readable causal shifts.", "outcomes": ["A05-LO1 — beat boundaries", "A05-LO2 — tactics", "A05-LO3 — refusal", "A05-LO4 — scene rhythm", "A05-LO5 — continuity of goal"]},
{"ord": 5, "topic_id": "A06", "course_name": "Acting for Camera", "stage": "L1", "title": "Given circumstances and subtext", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "**Given circumstances** are concrete facts: who, where, when, events and relationships. **Subtext** is the meaning or intention beneath the spoken words. “The food is getting cold” may really mean “Please stop avoiding our argument,” depending on evidence in the scene. Subtext should sharpen behavior, not become a secret essay viewers cannot see. **Demonstrate:** kitchen dialogue with and without a concealed grievance. **Pitfall:** inventing subtext that contradicts explicit circumstances. **Practice:** add subtext notes to four lines, then show them through looks and pauses. **Evidence:** a partner can infer the concealed need.", "outcomes": ["A06-LO1 — given circumstances", "A06-LO2 — subtext", "A06-LO3 — consistency", "A06-LO4 — ordinary dialogue", "A06-LO5 — partner inference"]},
{"ord": 6, "topic_id": "A07", "course_name": "Acting for Camera", "stage": "L1", "title": "Imagination and healthy emotion", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "Emotion can emerge from attention, objectives, imagery, physical action and partner interaction. No student must recount trauma or force distress to achieve an authentic take. A performer can build safe fictional specifics, a sensory environment and actionable stakes, then exit the role with grounding and de-roling. **Demonstrate:** a worried parent scene through attentive listening rather than forced tears. **Pitfall:** using personal psychological harm as a shortcut. **Practice:** devise two safe imaginary circumstances and a post-scene reset. **Evidence:** repeatable, bounded emotional availability.", "outcomes": ["A07-LO1 — emotional preparation", "A07-LO2 — safe boundaries", "A07-LO3 — emotion through action", "A07-LO4 — repetition", "A07-LO5 — de-roling"]},
{"ord": 7, "topic_id": "A08", "course_name": "Acting for Camera", "stage": "L1", "title": "Listening and reactions", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "On screen, a reaction can carry more story than a speech. A listening actor observes the partner, absorbs new information, and allows it to alter timing, body and intention. Listening is an active task, even when the actor has no lines. In a two-shot and close-up, compare waiting for a cue with genuinely processing the announcement “I sold the house.” **Pitfall:** rehearsing your next line mentally. **Practice:** shoot the same exchange twice with a changed, unknown partner choice. **Evidence:** responses genuinely track the stimulus.", "outcomes": ["A08-LO1 — active listening", "A08-LO2 — unspoken acting", "A08-LO3 — surprise", "A08-LO4 — timing", "A08-LO5 — eyeline connection"]},
{"ord": 8, "topic_id": "A09", "course_name": "Acting for Camera", "stage": "L2", "title": "Physicality and status", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "Posture, space, movement tempo and gesture can express occupation, age, health, status or emotional pressure without caricature. External choices must arise from character and social situation, not stereotypes about class or disability. **Demonstrate:** who controls space during a job interview; adjust a chair and eyeline. **Pitfall:** fidgeting to signal “nervous.” **Practice:** perform identical dialogue with two different status relationships. **Evidence:** purposeful and consistent physical choices.", "outcomes": ["A09-LO1 — status through space", "A09-LO2 — gesture economy", "A09-LO3 — character specificity", "A09-LO4 — tempo", "A09-LO5 — continuity"]},
{"ord": 9, "topic_id": "A10", "course_name": "Acting for Camera", "stage": "L2", "title": "Voice and dialogue clarity", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "Support clear speech with relaxed breath and unforced articulation. Camera dialogue rarely needs stage projection when a boom/lavalier is correctly placed. Anger or whispers must remain intelligible without shouting or vocal strain. Observe consonant clarity, pace, breath groups and the mic placement plan. **Demonstrate:** noisy roadside dialogue recorded with and without vocal discipline. **Pitfall:** tightening the throat for intensity. **Practice:** read an 80-word monologue at three dynamics while keeping meaning intelligible. **Evidence:** clear consonants, sustainable voice, stable level.", "outcomes": ["A10-LO1 — breath groups", "A10-LO2 — diction", "A10-LO3 — mic awareness", "A10-LO4 — high emotion", "A10-LO5 — listening test"]},
{"ord": 10, "topic_id": "A11", "course_name": "Acting for Camera", "stage": "L2", "title": "Language and accent ethics", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "Nollywood performance draws from English, Nigerian Pidgin and many African languages. Language choice signals home, community, intimacy, power and identity. Obtain pronunciation coaching and speaker review; document whether code-switching is written or improvised. An accent should be credible to character and region, not a joke unless the story intentionally and responsibly critiques it. **Demonstrate:** the same request to a parent, a friend and an employer. **Pitfall:** flattening communities into stock accents. **Practice:** build a pronunciation and code-switching sheet with a competent speaker. **Evidence:** clear intention and respectful consistency.", "outcomes": ["A11-LO1 — code-switching", "A11-LO2 — pronunciation", "A11-LO3 — dialect respect", "A11-LO4 — continuity", "A11-LO5 — translation"]},
{"ord": 11, "topic_id": "A12", "course_name": "Acting for Camera", "stage": "L2", "title": "Shot size and performance scale", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "A close-up magnifies small changes around eyes, mouth and breath; a wide shot communicates spatial behavior and relationship. The useful question is not “do less always,” but “what must the audience read at this distance?” Match performance energy to the dramatic event while calibrating size and physical continuity. **Demonstrate:** one revelation in wide, medium and close-up. **Pitfall:** overacting facial expression in tight framing or becoming inert in a wide. **Practice:** adapt the same beat to three shot sizes. **Evidence:** clear objective in all three.", "outcomes": ["A12-LO1 — wide shot", "A12-LO2 — close-up", "A12-LO3 — medium shot", "A12-LO4 — coverage matching", "A12-LO5 — emotional scale"]},
{"ord": 12, "topic_id": "A13", "course_name": "Acting for Camera", "stage": "L2", "title": "Eyelines and screen direction", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "Actors usually look at an agreed off-camera eyeline near, not into, the lens unless the script/design calls for direct address. An established axis helps maintain consistent screen direction in a conversation, though directors may cross it intentionally with clear visual motivation. Performance must stay with the partner while respecting the camera/eyeline plan. **Demonstrate:** diagram the axis for two actors at a table; compare wrong and right eyelines in edit. **Pitfall:** following the moving camera with one's gaze. **Practice:** mark eyelines and shoot matching singles. **Evidence:** edit preserves audience geography.", "outcomes": ["A13-LO1 — off-camera eyeline", "A13-LO2 — 180-degree axis", "A13-LO3 — intentional axis crossing", "A13-LO4 — matching singles", "A13-LO5 — direct address"]},
{"ord": 13, "topic_id": "A14", "course_name": "Acting for Camera", "stage": "L2", "title": "Blocking and continuity", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "**Blocking** is planned movement in relation to partners, props and camera. A **mark** helps focus, lighting and composition. Continuity includes which hand lifts a cup, line timing, standing position and eyeline; the actor stays flexible when a director changes coverage. **Demonstrate:** same action across wide, over-shoulder and close-up. **Pitfall:** changing the gesture/prop hand between takes. **Practice:** make a continuity log from three takes and match a specific gesture. **Evidence:** cuts preserve movement and intention.", "outcomes": ["A14-LO1 — blocking", "A14-LO2 — marks", "A14-LO3 — prop hand", "A14-LO4 — timing", "A14-LO5 — change control"]},
{"ord": 14, "topic_id": "A15", "course_name": "Acting for Camera", "stage": "L2", "title": "Self-tape auditions", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "A strong self-tape prioritizes readable face, clear voice, neutral uncluttered background, correct framing, good light, controlled eyeline and following casting instructions. Respect file naming, slate requirements, deadlines, character context and privacy. Do not add distracting graphics or expensive equipment for its own sake. **Demonstrate:** poor and improved mobile-phone submissions. **Pitfall:** talking to the lens when a partner eyeline was requested. **Practice:** submit a named 60–90-second tape with self-evaluation. **Evidence:** casting-ready technical and creative quality.", "outcomes": ["A15-LO1 — framing", "A15-LO2 — eyeline", "A15-LO3 — sound", "A15-LO4 — instructions", "A15-LO5 — privacy"]},
{"ord": 15, "topic_id": "A16", "course_name": "Acting for Camera", "stage": "L2", "title": "Cold reads", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "A cold read is not a memory test. Quickly identify the relationship, turning point, objective and immediate stakes, then read with connection to partner and text. Prioritize comprehension over accent tricks or a fully fixed emotional result. When permitted, ask one concise, useful clarification question. **Demonstrate:** a 90-second preparation of unfamiliar sides. **Pitfall:** staring at the script through the partner's lines. **Practice:** prepare a short surprise scene with a timer. **Evidence:** coherent intention and responsive reading.", "outcomes": ["A16-LO1 — quick analysis", "A16-LO2 — turning point", "A16-LO3 — text handling", "A16-LO4 — clarification", "A16-LO5 — flexibility"]},
{"ord": 16, "topic_id": "A17", "course_name": "Acting for Camera", "stage": "L3", "title": "Improvisation and offers", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "Improvisation requires listening, accepting a playable offer, and advancing the scene with specific action. “Yes, and” means build cooperatively, not agree with harmful actions or surrender personal boundaries. Structure improv with where, relationship, objective and change. **Demonstrate:** a market-stall misunderstanding, then repeat with a new offer. **Pitfall:** blocking every partner idea or chasing jokes without stakes. **Practice:** improvise a one-minute conflict in a familiar local setting. **Evidence:** clear jointly built story.", "outcomes": ["A17-LO1 — offer", "A17-LO2 — accept and build", "A17-LO3 — boundaries", "A17-LO4 — stakes", "A17-LO5 — listening"]},
{"ord": 17, "topic_id": "A18", "course_name": "Acting for Camera", "stage": "L3", "title": "Ensemble rhythm", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "Dialogue rhythm depends on thought, subtext, listening and editing needs. Overlap can convey pressure or intimacy, but uncontrolled overlap may make recording and coverage difficult. Silence must carry activity, not emptiness. **Demonstrate:** family-dinner argument played once with pauses, once with controlled overlap; assess clarity in edit. **Pitfall:** a mechanically timed pause with no character reason. **Practice:** coordinate breath/overlap points with sound and director. **Evidence:** emotionally clear but cuttable sequence.", "outcomes": ["A18-LO1 — motivated pause", "A18-LO2 — controlled overlap", "A18-LO3 — ensemble listening", "A18-LO4 — sound plan", "A18-LO5 — editorial continuity"]},
{"ord": 18, "topic_id": "A19", "course_name": "Acting for Camera", "stage": "L3", "title": "Comedy and timing", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "Comedy often arises from a precise character objective meeting a frustrating obstacle. The performer may commit seriously to absurd circumstances rather than “announce the joke.” Set-up, expectation, reveal, reaction and edit duration all shape timing. Cultural humor needs context and care around marginalized identities. **Demonstrate:** two versions of a misdelivered parcel gag. **Pitfall:** laughing at one's own line or forcing mugging for camera. **Practice:** build a 30-second visual-comedy scene with no dialogue. **Evidence:** audience understands the reversal.", "outcomes": ["A19-LO1 — character objective", "A19-LO2 — setup", "A19-LO3 — reveal", "A19-LO4 — reaction", "A19-LO5 — ethical humor"]},
{"ord": 19, "topic_id": "A20", "course_name": "Acting for Camera", "stage": "L3", "title": "High-intensity drama safely", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "Grief, fear and conflict can be built from truthful objectives, safe substitution, breath, scene partners and repeatable physical actions. The director and student agree beforehand on physical boundaries, break cues and off-ramps. Repeated screaming or forced crying is not a quality metric. **Demonstrate:** a family-loss scene with controlled intensification and recovery. **Pitfall:** confusing exhaustion with emotional truth. **Practice:** record an intense beat twice, then use a short de-role routine. **Evidence:** consistent emotional story and wellbeing.", "outcomes": ["A20-LO1 — intensity", "A20-LO2 — repeatability", "A20-LO3 — consent", "A20-LO4 — recovery", "A20-LO5 — director feedback"]},
{"ord": 20, "topic_id": "A21", "course_name": "Acting for Camera", "stage": "L4", "title": "Intimacy and consent", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "Scenes involving nudity, simulated sex or other sensitive intimacy require clear advance discussion, specific consent, defined choreography and a qualified intimacy professional where applicable. Students may decline an exercise without academic retaliation; provide equivalent competencies through non-intimate scenes. Consent is ongoing and can be withdrawn. Never request learner nudity or improvised intimate touching. **Demonstrate:** fully clothed, non-intimate boundary negotiation and camera cheat. **Pitfall:** treating an earlier yes as blanket approval. **Practice:** document a fictional scene's boundaries, closure and escalation contact. **Evidence:** precise consent communication.", "outcomes": ["A21-LO1 — advance notice", "A21-LO2 — withdrawal", "A21-LO3 — qualified coordination", "A21-LO4 — alternative exercise", "A21-LO5 — closed-set controls"]},
{"ord": 21, "topic_id": "A22", "course_name": "Acting for Camera", "stage": "L4", "title": "Stunt-aware acting", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "An actor sells danger through reaction, eyeline, timing and edited coverage while specialists control the actual hazard. Only qualified personnel design and supervise stunts, weapons, vehicles, falls and fight choreography. A student may rehearse a harmless camera-angle illusion but must never stage actual strikes or dangerous falls. **Demonstrate:** implied impact using separate actor reaction and sound effect, with no contact. **Pitfall:** “making it realistic” with real impact. **Practice:** plan a zero-contact confrontation and risk checklist. **Evidence:** believable edit with no real hazard.", "outcomes": ["A22-LO1 — qualified supervision", "A22-LO2 — reaction timing", "A22-LO3 — camera cheat", "A22-LO4 — risk briefing", "A22-LO5 — safe student exercise"]},
{"ord": 22, "topic_id": "A23", "course_name": "Acting for Camera", "stage": "L4", "title": "Design and continuity collaboration", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "Wardrobe silhouettes, fabrics, makeup continuity, personal props and physical environment tell character history. The performer should know what each prop means, how it is handled and what changes between scenes. In a hospital/office set, accuracy depends on approved reference and technical advisers, not the actor inventing clinical behavior or confidential data. **Demonstrate:** continuity photo board and three takes with a handbag or medical chart prop. **Pitfall:** changing a costume/prop action unlogged. **Practice:** create a character look-and-prop continuity sheet. **Evidence:** defensible story choice and matched takes.", "outcomes": ["A23-LO1 — character look", "A23-LO2 — continuity photos", "A23-LO3 — prop handling", "A23-LO4 — set accuracy", "A23-LO5 — privacy"]},
{"ord": 23, "topic_id": "A24", "course_name": "Acting for Camera", "stage": "L4", "title": "ADR, reel and career", "status": "DRAFT — FACULTY REVIEW", "media": "BRIEF ONLY", "lesson": "**ADR** replaces or supplements recorded dialogue while matching timing, emotion and acoustics. **Pickups** collect missing shots or lines that support the edit. A strong actor reel opens with a clear, recent, well-shot moment, gives accurate credit, uses only cleared footage and removes filler. Learn release terms, agent/manager distinction, safe audition reporting and transparent professional expectations. **Demonstrate:** align a short ADR line to picture and cut a concise reel. **Pitfall:** placing copyrighted uncleared scenes or misleading credits in a public reel. **Practice:** submit a 60–90-second permissions-checked reel and a career plan. **Evidence:** credible, ethical, accessible portfolio.", "outcomes": ["A24-LO1 — ADR sync", "A24-LO2 — pickup shot", "A24-LO3 — reel opening", "A24-LO4 — rights check", "A24-LO5 — career integrity"]},
{"ord": 24, "topic_id": "C01-T1", "course_name": "Story & Scriptwriting", "stage": "survey", "title": "Logline, premise and theme", "status": "TOPIC BRIEF — EXPANSION REQUIRED", "media": "NOT PRODUCED", "lesson": "The student explains logline, premise and theme, demonstrates the critical decision in a contained African production scenario, and justifies a safe, affordable professional workflow. Guided practice: state protagonist, goal, obstacle and hook. Study a contrasting before-and-after example and annotate the production evidence. Faculty expansion must add full article, photographed/filmed examples, audio script, exercises and topic-specific assessment.", "outcomes": ["C01-T1-LO1 — state protagonist, goal, obstacle and hook"]},
{"ord": 25, "topic_id": "C01-T2", "course_name": "Story & Scriptwriting", "stage": "survey", "title": "Character desire and conflict", "status": "TOPIC BRIEF — EXPANSION REQUIRED", "media": "NOT PRODUCED", "lesson": "The student explains character desire and conflict, demonstrates the critical decision in a contained African production scenario, and justifies a safe, affordable professional workflow. Guided practice: link desire to external opposition. Study a contrasting before-and-after example and annotate the production evidence. Faculty expansion must add full article, photographed/filmed examples, audio script, exercises and topic-specific assessment.", "outcomes": ["C01-T2-LO1 — link desire to external opposition"]},
{"ord": 26, "topic_id": "C01-T3", "course_name": "Story & Scriptwriting", "stage": "survey", "title": "Scene beats, dialogue and subtext", "status": "TOPIC BRIEF — EXPANSION REQUIRED", "media": "NOT PRODUCED", "lesson": "The student explains scene beats, dialogue and subtext, demonstrates the critical decision in a contained African production scenario, and justifies a safe, affordable professional workflow. Guided practice: let scene action and subtext change. Study a contrasting before-and-after example and annotate the production evidence. Faculty expansion must add full article, photographed/filmed examples, audio script, exercises and topic-specific assessment.", "outcomes": ["C01-T3-LO1 — let scene action and subtext change"]},
{"ord": 27, "topic_id": "C01-T4", "course_name": "Story & Scriptwriting", "stage": "survey", "title": "Rewrites, coverage and script format", "status": "TOPIC BRIEF — EXPANSION REQUIRED", "media": "NOT PRODUCED", "lesson": "The student explains rewrites, coverage and script format, demonstrates the critical decision in a contained African production scenario, and justifies a safe, affordable professional workflow. Guided practice: revise from specific reader evidence. Study a contrasting before-and-after example and annotate the production evidence. Faculty expansion must add full article, photographed/filmed examples, audio script, exercises and topic-specific assessment.", "outcomes": ["C01-T4-LO1 — revise from specific reader evidence"]},
{"ord": 28, "topic_id": "C02-T1", "course_name": "Directing & Casting", "stage": "survey", "title": "Interpret theme and tone", "status": "TOPIC BRIEF — EXPANSION REQUIRED", "media": "NOT PRODUCED", "lesson": "The student explains interpret theme and tone, demonstrates the critical decision in a contained African production scenario, and justifies a safe, affordable professional workflow. Guided practice: derive staging choices from theme. Study a contrasting before-and-after example and annotate the production evidence. Faculty expansion must add full article, photographed/filmed examples, audio script, exercises and topic-specific assessment.", "outcomes": ["C02-T1-LO1 — derive staging choices from theme"]},
